const m=["Growth rates and index numbers","Demand and elasticity","Consumer theory","Producers and costs","Market structure and games","Welfare and taxes","National accounts and the macroeconomy","Growth models","Money, inflation and interest","Open economy","Finance and discounting","Probability","Statistics and inference","Regression and causal inference","Time series","Inequality and poverty","Labour and human capital"],e=(a,t,i)=>({id:a,label:t,value:i}),n=a=>a,c=[n({id:"growth-rate",area:"Growth rates and index numbers",name:"Percentage growth rate",level:"beginner",tex:"g = \\frac{x_t - x_{t-1}}{x_{t-1}} \\times 100",symbols:[["x_t","value this period"],["x_{t-1}","value last period"]],brief:"How much a variable grew, in percent of its starting value.",meaning:"A 5 percent growth rate means the variable is 5 percent larger than a period earlier, whatever its units.",example:"GDP rises from 4,000 to 4,200: $g = 200/4000 \\times 100 = 5$ percent.",scenario:"**Case:** remittance inflows rise from Rs 1,000 billion to Rs 1,150 billion: growth is 15 percent. Imports rise 10 percent from Rs 1,600 billion, which is Rs 160 billion. So imports grew more in rupees even though remittances grew faster in percent. Always check both the rate and the base.",inputs:[e("a","Previous value",4e3),e("b","Current value",4200)],calc:({a,b:t})=>[{label:"Growth",value:(t-a)/a*100,unit:"%"}]}),n({id:"log-growth",area:"Growth rates and index numbers",name:"Log growth rate",level:"intermediate",topic:"functional-form",tex:"g \\approx 100\\,(\\ln x_t - \\ln x_{t-1})",symbols:[["\\ln","natural logarithm"]],brief:"Growth measured as the difference in logs; additive over time and close to the percentage change for small changes.",meaning:"Log growth over several periods is the sum of each period's log growth, which makes averages and regressions easier.",example:"From 4,000 to 4,200: $100 \\ln(1.05) = 4.88$, close to the 5 percent exact rate.",scenario:"**Case:** a real GDP index rises from 100 to 104, then falls back to 100. Percentage changes are +4 and -3.85 percent, which seem to average +0.08 percent although nothing changed. Log changes are +3.92 and -3.92, which sum to exactly zero. This is why growth regressions use logs.",inputs:[e("a","Previous value",4e3),e("b","Current value",4200)],calc:({a,b:t})=>[{label:"Log growth",value:100*Math.log(t/a),unit:"%"},{label:"Exact growth",value:(t/a-1)*100,unit:"%"}]}),n({id:"cagr",area:"Growth rates and index numbers",name:"Compound annual growth rate",level:"beginner",tex:"g = \\left(\\frac{x_T}{x_0}\\right)^{1/T} - 1",symbols:[["x_0","starting value"],["x_T","value after T years"],["T","number of years"]],brief:"The constant yearly growth rate that takes a variable from its start to its end value.",meaning:"It smooths out year to year swings so periods of different length can be compared.",example:"Income doubles in 10 years: $2^{1/10} - 1 = 7.18$ percent a year.",scenario:"**Case (illustrative numbers):** GDP per person rises from 700 to 1,400 US dollars over 12 years: $2^{1/12} - 1 = 5.95$ percent a year. In dollars this mixes real growth, inflation and exchange rate changes, so for real growth use a constant price series in rupees.",inputs:[e("a","Start value",1e3),e("b","End value",2e3),e("T","Years",10)],calc:({a,b:t,T:i})=>[{label:"Annual growth",value:((t/a)**(1/i)-1)*100,unit:"%"}]}),n({id:"rule-70",area:"Growth rates and index numbers",name:"Rule of 70 (doubling time)",level:"beginner",tex:"t_{double} \\approx \\frac{70}{g\\,(\\%)}",symbols:[["g","growth rate in percent per year"]],brief:"A quick way to find how long something takes to double.",meaning:"Exact doubling time is $\\ln 2 / \\ln(1+g)$; 70 approximates $100 \\ln 2$.",example:"At 4 percent growth, $70/4 = 17.5$ years (exactly 17.67). At 7 percent, about 10 years; at 2 percent, 35 years.",scenario:"**Case:** if income per person in Nepal grows 4 percent a year, average income doubles in about 17.5 years, before a child born today turns 18. At 2 percent it takes 35 years, most of a working life. Small differences in growth rates compound into very different futures.",inputs:[e("g","Growth rate (%)",4)],calc:({g:a})=>[{label:"Rule of 70",value:70/a,unit:"years"},{label:"Exact",value:Math.log(2)/Math.log(1+a/100),unit:"years"}]}),n({id:"laspeyres",area:"Growth rates and index numbers",name:"Laspeyres price index",level:"beginner",topic:"national-accounts",tex:"L = \\frac{\\sum_i p_{i,t}\\,q_{i,0}}{\\sum_i p_{i,0}\\,q_{i,0}} \\times 100",symbols:[["p_{i,t}","price of good i now"],["q_{i,0}","base period quantity"]],brief:"The cost of a fixed base period basket at today's prices, relative to its original cost.",meaning:"The CPI is a Laspeyres type index. It overstates the cost of living because people substitute toward goods that became relatively cheaper.",example:"A basket cost 500 in the base year and 560 now: index 112, so prices rose 12 percent.",scenario:"**Case:** a base year basket is 20 kg rice at Rs 80, 5 kg lentils at Rs 160 and 10 litres of milk at Rs 90: Rs 3,300. Today the same basket costs Rs 3,800 (prices 90, 200 and 100), so the index is 115.2 and prices rose 15.2 percent. If households switch from dearer lentils to rice, their true cost of living rose less: the substitution bias of a fixed basket.",inputs:[e("a","Basket cost in base year",500),e("b","Same basket now",560)],calc:({a,b:t})=>[{label:"Index",value:t/a*100},{label:"Inflation",value:(t/a-1)*100,unit:"%"}]}),n({id:"real-value",area:"Growth rates and index numbers",name:"Real value with a price index",level:"beginner",tex:"\\text{Real} = \\frac{\\text{Nominal}}{\\text{Price index}/100}",symbols:[["\\text{Price index}","base year = 100"]],brief:"Converts a money amount into base year prices, removing inflation.",meaning:"Real values compare purchasing power across years.",example:"A salary of 50,000 with a price index of 125 is worth 40,000 in base year rupees.",scenario:"**Case (illustrative CPI):** a monthly minimum wage rises from Rs 13,450 to Rs 17,300, a nominal rise of 28.6 percent, while the price index rises from 100 to 125. The new wage is worth Rs 13,840 in base year rupees, so the real rise is only 2.9 percent.",inputs:[e("n","Nominal value",5e4),e("p","Price index",125)],calc:({n:a,p:t})=>[{label:"Real value",value:a/(t/100)}]}),n({id:"price-elasticity",area:"Demand and elasticity",name:"Price elasticity of demand (point)",level:"beginner",topic:"single-calculus",tex:"\\varepsilon = \\frac{\\partial Q}{\\partial P}\\cdot\\frac{P}{Q}",symbols:[["Q","quantity demanded"],["P","price"]],brief:"The percentage change in quantity for a one percent change in price.",meaning:"|e| > 1: elastic, revenue falls when price rises. |e| < 1: inelastic, revenue rises when price rises.",example:"Slope -2, price 10, quantity 40: $\\varepsilon = -2 \\times 10/40 = -0.5$, inelastic.",scenario:"**Case:** NEA raises the average tariff 10 percent, from Rs 10 to Rs 11 a unit. If household demand elasticity is -0.3, use falls 3 percent and revenue rises about $1.10 \\times 0.97 - 1 = 6.7$ percent. If elasticity were -1.5, revenue would fall 6.5 percent. Knowing the elasticity decides whether a tariff rise helps NEA's finances.",inputs:[e("s","Slope dQ/dP",-2),e("p","Price",10),e("q","Quantity",40)],calc:({s:a,p:t,q:i})=>[{label:"Elasticity",value:a*t/i}]}),n({id:"arc-elasticity",area:"Demand and elasticity",name:"Arc (midpoint) elasticity",level:"beginner",tex:"\\varepsilon = \\frac{(Q_2 - Q_1)/\\bar Q}{(P_2 - P_1)/\\bar P}",symbols:[["\\bar Q, \\bar P","averages of the two points"]],brief:"Elasticity between two observed points, the same in both directions.",meaning:"Using averages avoids getting a different answer depending on which point you start from.",example:"Price 10 to 12, quantity 100 to 90: $(-10/95)/(2/11) = -0.58$.",scenario:"**Case (illustrative):** a city bus fare rises from Rs 25 to Rs 30 and daily passengers fall from 40,000 to 36,000. Arc elasticity is $(-4000/38000)/(5/27.5) = -0.58$: inelastic, so fare revenue rises from Rs 1,000,000 to Rs 1,080,000 a day.",inputs:[e("p1","Price 1",10),e("p2","Price 2",12),e("q1","Quantity 1",100),e("q2","Quantity 2",90)],calc:({p1:a,p2:t,q1:i,q2:r})=>[{label:"Arc elasticity",value:(r-i)/((i+r)/2)/((t-a)/((a+t)/2))}]}),n({id:"income-elasticity",area:"Demand and elasticity",name:"Income elasticity of demand",level:"beginner",tex:"\\eta = \\frac{\\%\\Delta Q}{\\%\\Delta M}",symbols:[["M","income"]],brief:"How demand responds to income.",meaning:"Above 1: luxury; between 0 and 1: necessity; below 0: inferior good.",example:"Income up 10 percent, demand up 4 percent: $\\eta = 0.4$, a necessity.",scenario:"As remittance incomes rise, demand for rice grows slowly (necessity) while demand for motorbikes grows fast (luxury).",inputs:[e("q","% change in quantity",4),e("m","% change in income",10)],calc:({q:a,m:t})=>[{label:"Income elasticity",value:a/t}]}),n({id:"cross-elasticity",area:"Demand and elasticity",name:"Cross-price elasticity",level:"beginner",tex:"\\varepsilon_{xy} = \\frac{\\%\\Delta Q_x}{\\%\\Delta P_y}",symbols:[["Q_x","demand for x"],["P_y","price of y"]],brief:"How demand for one good responds to another good's price.",meaning:"Positive: substitutes. Negative: complements.",example:"Gas price up 20 percent, induction stove sales up 10 percent: 0.5, substitutes.",scenario:"**Case (illustrative):** when the price of an LPG cylinder rises 20 percent, sales of induction stoves in a town rise 30 percent: cross elasticity 1.5, strong substitutes. Electricity tariffs and stove subsidies therefore affect LPG imports, and with them Nepal's trade deficit.",inputs:[e("q","% change in quantity of x",10),e("p","% change in price of y",20)],calc:({q:a,p:t})=>[{label:"Cross elasticity",value:a/t}]}),n({id:"revenue-elasticity",area:"Demand and elasticity",name:"Marginal revenue and elasticity",level:"intermediate",tex:"MR = P\\left(1 + \\frac{1}{\\varepsilon}\\right)",symbols:[["\\varepsilon","price elasticity (negative)"]],brief:"Links marginal revenue to price and elasticity.",meaning:"MR is positive only where demand is elastic; a monopolist never sets price on the inelastic part of demand.",example:"P = 60, e = -2: $MR = 60(1 - 0.5) = 30$.",scenario:"**Case:** a sole cable provider charges Rs 600 a month where demand elasticity is -0.8. Then $MR = 600(1 - 1.25) = -150$: losing a subscriber by raising the price would raise revenue and cut costs. So this price cannot maximise profit; the provider raises it until demand becomes elastic.",inputs:[e("p","Price",60),e("e","Elasticity",-2)],calc:({p:a,e:t})=>[{label:"Marginal revenue",value:a*(1+1/t)}]}),n({id:"mrs",area:"Consumer theory",name:"Marginal rate of substitution",level:"beginner",topic:"preferences-utility",tex:"MRS_{xy} = \\frac{MU_x}{MU_y}",symbols:[["MU","marginal utility"]],brief:"How many units of y a consumer will give up for one more x, staying equally happy.",meaning:"It is the absolute slope of the indifference curve. At the optimum it equals the price ratio.",example:"Cobb-Douglas $U = x^{0.5}y^{0.5}$ at x = 10, y = 20: MRS = y/x = 2.",scenario:"**Case:** a farmer with 10 kg of lentils and 20 kg of maize has Cobb-Douglas preferences with equal weights, so MRS = 2: she values 1 kg of lentils at 2 kg of maize. In the market 1 kg of lentils buys 3 kg of maize, more than she values it, so she should sell some lentils for maize until her MRS rises to 3.",inputs:[e("a","Alpha (exponent on x)",.5),e("x","x",10),e("y","y",20)],calc:({a,x:t,y:i})=>[{label:"MRS (Cobb-Douglas)",value:a/(1-a)*(i/t)}]}),n({id:"tangency",area:"Consumer theory",name:"Optimal choice condition",level:"intermediate",topic:"consumer-choice",tex:"\\frac{MU_x}{p_x} = \\frac{MU_y}{p_y}",symbols:[["p","prices"]],brief:"At the optimum, the last rupee spent on each good brings the same extra utility.",meaning:"If $MU_x/p_x$ were larger, shifting a rupee from y to x would raise utility.",example:"If $MU_x = 8$, $p_x = 4$ and $MU_y = 6$, $p_y = 2$: 2 versus 3 per rupee, so buy more y.",scenario:"**Case:** a family's last rupee on extra tuition classes adds 3 units of satisfaction while the last rupee on meat adds 2. Moving Rs 1,000 a month from meat to tuition raises their wellbeing, and they should keep shifting until the two are equal per rupee.",inputs:[e("mx","MU of x",8),e("px","Price of x",4),e("my","MU of y",6),e("py","Price of y",2)],calc:({mx:a,px:t,my:i,py:r})=>[{label:"MU per rupee on x",value:a/t},{label:"MU per rupee on y",value:i/r}]}),n({id:"cd-demand",area:"Consumer theory",name:"Cobb-Douglas demand",level:"intermediate",topic:"lagrange",tex:"x^* = \\frac{\\alpha M}{p_x},\\quad y^* = \\frac{(1-\\alpha) M}{p_y}",symbols:[["\\alpha","spending share on x"],["M","income"]],brief:"With Cobb-Douglas utility, consumers spend a fixed share of income on each good.",meaning:"Income elasticity is 1 and own price elasticity is -1; cross price elasticity is 0.",example:"$\\alpha = 0.3$, M = 1000, $p_x = 15$: $x^* = 20$.",scenario:"A household spending 30 percent of income on food buys less food in kg when food prices rise but spends the same amount.",inputs:[e("a","Alpha",.3),e("M","Income",1e3),e("px","Price of x",15),e("py","Price of y",5)],calc:({a,M:t,px:i,py:r})=>[{label:"x*",value:a*t/i},{label:"y*",value:(1-a)*t/r}]}),n({id:"slutsky",area:"Consumer theory",name:"Slutsky equation",level:"advanced",topic:"duality-slutsky",tex:"\\frac{\\partial x}{\\partial p} = \\frac{\\partial h}{\\partial p} - x\\,\\frac{\\partial x}{\\partial M}",symbols:[["x","Marshallian demand"],["h","Hicksian demand"],["M","income"]],brief:"Splits a price effect into a substitution effect and an income effect.",meaning:"The substitution effect is always negative; a Giffen good needs a large positive income term.",example:"Substitution effect -3, demand 10, income effect per rupee 0.2: total $= -3 - 10(0.2) = -5$.",scenario:"When rice prices rise, poor households cut rice partly because it is dearer and partly because they are poorer.",inputs:[e("s","Substitution effect dh/dp",-3),e("x","Quantity x",10),e("dm","dx/dM",.2)],calc:({s:a,x:t,dm:i})=>[{label:"Total effect dx/dp",value:a-t*i}]}),n({id:"expected-utility",area:"Consumer theory",name:"Expected utility",level:"intermediate",tex:"EU = \\sum_i p_i\\, u(w_i)",symbols:[["p_i","probability of outcome i"],["u","utility function"]],brief:"The probability weighted average of utilities.",meaning:"With concave u, people prefer a sure amount to a gamble with the same mean.",example:"With $u = \\ln w$: 50 percent of 100 and 50 percent of 400 gives $EU = 5.30$ and certainty equivalent 200.",scenario:"**Case:** a worker earning Rs 400,000 a year in Nepal could migrate: 80 percent chance of Rs 1,000,000 net, 20 percent chance that contract problems leave only Rs 200,000. Expected value is Rs 840,000. With log utility the certainty equivalent is about Rs 725,000: still well above 400,000, so migration pays, but risk costs the worker about Rs 115,000 of value. Better information about employers would raise that value.",inputs:[e("p","Probability of good outcome",.5),e("a","Good outcome",400),e("b","Bad outcome",100)],calc:({p:a,a:t,b:i})=>{const r=a*Math.log(t)+(1-a)*Math.log(i);return[{label:"Expected value",value:a*t+(1-a)*i},{label:"Expected log utility",value:r},{label:"Certainty equivalent",value:Math.exp(r)}]}}),n({id:"cobb-douglas",area:"Producers and costs",name:"Cobb-Douglas production function",level:"beginner",topic:"producer-theory",tex:"Q = A K^{\\alpha} L^{\\beta}",symbols:[["A","productivity"],["K","capital"],["L","labour"]],brief:"The workhorse production function.",meaning:"$\\alpha$ and $\\beta$ are output elasticities; $\\alpha + \\beta$ shows returns to scale (1 constant, above 1 increasing).",example:"A = 2, K = 16, L = 25, $\\alpha = \\beta = 0.5$: $Q = 2 \\times 4 \\times 5 = 40$.",scenario:"Growth accounting for Nepal uses this to split growth into capital, labour and productivity.",inputs:[e("A","A",2),e("K","K",16),e("L","L",25),e("a","alpha",.5),e("b","beta",.5)],calc:({A:a,K:t,L:i,a:r,b:o})=>[{label:"Output",value:a*t**r*i**o},{label:"Returns to scale (alpha + beta)",value:r+o}]}),n({id:"marginal-product",area:"Producers and costs",name:"Marginal product of labour (Cobb-Douglas)",level:"intermediate",tex:"MP_L = \\beta\\,\\frac{Q}{L}",symbols:[["Q/L","average product of labour"]],brief:"Extra output from one more worker.",meaning:"In Cobb-Douglas the marginal product is a fixed fraction of the average product; competitive wages equal it.",example:"Q = 40, L = 25, $\\beta = 0.5$: $MP_L = 0.8$.",scenario:"**Case:** with $Q = K^{0.4}L^{0.6}$, the marginal product of labour is $0.6(K/L)^{0.4}$. Doubling machines per worker raises it by $2^{0.4} = 1.32$, so competitive wages rise 32 percent. That is why investment in equipment raises wages in Nepal's factories.",inputs:[e("b","beta",.5),e("Q","Output",40),e("L","Labour",25)],calc:({b:a,Q:t,L:i})=>[{label:"MP of labour",value:a*t/i}]}),n({id:"mrts",area:"Producers and costs",name:"Marginal rate of technical substitution",level:"intermediate",tex:"MRTS = \\frac{MP_L}{MP_K} = \\frac{\\beta}{\\alpha}\\,\\frac{K}{L}",symbols:[["MP","marginal products"]],brief:"How much capital can replace one worker keeping output fixed.",meaning:"Cost minimisation sets MRTS equal to the wage rental ratio w/r.",example:"$\\alpha = \\beta$, K = 16, L = 25: MRTS = 0.64.",scenario:"**Case:** a rice mill with K = 16 and L = 25 and equal exponents has MRTS 0.64. If the wage relative to the rental of a machine is 1, a worker adds less output per rupee than a machine, so the mill should mechanise until MRTS rises to 1. Rising wages from labour migration push Nepali farms and mills toward machines for exactly this reason.",inputs:[e("a","alpha",.5),e("b","beta",.5),e("K","K",16),e("L","L",25)],calc:({a,b:t,K:i,L:r})=>[{label:"MRTS",value:t/a*(i/r)}]}),n({id:"average-cost",area:"Producers and costs",name:"Average and marginal cost",level:"beginner",tex:"AC = \\frac{TC}{Q},\\quad MC = \\frac{\\Delta TC}{\\Delta Q}",symbols:[["TC","total cost"]],brief:"Cost per unit and cost of one more unit.",meaning:"Average cost falls while marginal cost is below it, and rises when marginal is above it.",example:"TC rises from 1,000 to 1,060 when output rises from 100 to 101: MC = 60, AC = 10.5.",scenario:"Should a printing press accept an extra order at 50 per copy? Compare with marginal, not average, cost.",inputs:[e("c1","Cost before",1e3),e("c2","Cost after",1060),e("q1","Output before",100),e("q2","Output after",101)],calc:({c1:a,c2:t,q1:i,q2:r})=>[{label:"Marginal cost",value:(t-a)/(r-i)},{label:"Average cost after",value:t/r}]}),n({id:"profit-max",area:"Producers and costs",name:"Profit maximisation",level:"beginner",tex:"\\pi = TR - TC,\\quad MR = MC",symbols:[["\\pi","profit"]],brief:"A firm maximises profit where marginal revenue equals marginal cost.",meaning:"For a competitive firm MR is the price, so P = MC.",example:"Price 30, MC = 10 + 2Q: Q = 10.",scenario:"**Case:** a poultry farm sells birds at Rs 300 and its marginal cost is $100 + 0.5Q$ per bird. It raises $Q = 400$ birds a batch. If feed prices push the marginal cost intercept to 150, output falls to 300 birds: supply responds to costs through MC.",inputs:[e("p","Price",30),e("a","MC intercept",10),e("b","MC slope",2)],calc:({p:a,a:t,b:i})=>[{label:"Profit maximising Q",value:(a-t)/i}]}),n({id:"monopoly-markup",area:"Market structure and games",name:"Monopoly markup (Lerner rule)",level:"intermediate",topic:"producer-theory",tex:"\\frac{P - MC}{P} = \\frac{1}{|\\varepsilon|}",symbols:[["\\varepsilon","demand elasticity"]],brief:"A monopolist's markup depends only on the elasticity of demand.",meaning:"The less elastic demand is, the larger the markup.",example:"MC = 30, e = -3: $P = 30/(1 - 1/3) = 45$.",scenario:"Why a sole supplier in a remote market charges higher markups than one facing competition.",inputs:[e("mc","Marginal cost",30),e("e","Elasticity (positive number)",3)],calc:({mc:a,e:t})=>[{label:"Price",value:a/(1-1/t)},{label:"Lerner index",value:1/t}]}),n({id:"cournot",area:"Market structure and games",name:"Cournot equilibrium with n firms",level:"advanced",topic:"game-theory-nash",tex:"q_i = \\frac{a - c}{b(n + 1)},\\quad P = \\frac{a + nc}{n + 1}",symbols:[["a, b","demand P = a - bQ"],["c","marginal cost"],["n","number of firms"]],brief:"Output and price when n identical firms compete in quantities.",meaning:"As n grows the price falls toward marginal cost: competition emerges from numbers.",example:"a = 100, b = 1, c = 10, n = 2: $q_i = 30$, P = 40.",scenario:"**Case:** with demand $P = 100 - Q$ and marginal cost 10, two mobile operators set a price of 40. A third operator lowers it to 32.5, a fourth to 28. Each entrant lowers prices toward cost, which is the economic case for licensing more competitors.",inputs:[e("a","a",100),e("b","b",1),e("c","Marginal cost",10),e("n","Firms",2)],calc:({a,b:t,c:i,n:r})=>[{label:"Output per firm",value:(a-i)/(t*(r+1))},{label:"Price",value:(a+r*i)/(r+1)}]}),n({id:"hhi",area:"Market structure and games",name:"Herfindahl-Hirschman index",level:"beginner",tex:"HHI = \\sum_i s_i^2",symbols:[["s_i","market share of firm i in percent"]],brief:"A measure of market concentration.",meaning:"Ranges up to 10,000 (monopoly). Competition authorities scrutinise mergers that raise HHI in concentrated markets.",example:"Shares 40, 30, 20, 10: HHI = 1600 + 900 + 400 + 100 = 3000.",scenario:"**Case:** twenty banks with 5 percent each give HHI 500. After mergers into ten banks of 10 percent each, HHI is 1,000. Competition authorities usually start to worry above about 1,800 (the threshold for highly concentrated markets in the 2023 US merger guidelines), but local markets in a district can be far more concentrated than the national figure.",inputs:[e("a","Share 1 (%)",40),e("b","Share 2 (%)",30),e("c","Share 3 (%)",20),e("d","Share 4 (%)",10)],calc:({a,b:t,c:i,d:r})=>[{label:"HHI",value:a*a+t*t+i*i+r*r}]}),n({id:"mixed-strategy",area:"Market structure and games",name:"Mixed strategy indifference",level:"advanced",tex:"p = \\frac{d - b}{(a - b) - (c - d)}",symbols:[["a, b, c, d","column player's payoffs: (Up,Left), (Down,Left), (Up,Right), (Down,Right)"]],brief:"The probability that makes the other player indifferent between strategies.",meaning:"Each player's mix depends on the other's payoffs, not their own.",example:"Payoffs 3, 0, 1, 2: p = (2 - 0)/(3 - 0 - 1 + 2) = 0.5.",scenario:"Random tax audits: the authority mixes so that evaders are indifferent between evading and complying.",inputs:[e("a","(Up, Left)",3),e("b","(Down, Left)",0),e("c","(Up, Right)",1),e("d","(Down, Right)",2)],calc:({a,b:t,c:i,d:r})=>[{label:"p(Up)",value:(r-t)/(a-t-i+r)}]}),n({id:"consumer-surplus",area:"Welfare and taxes",name:"Consumer surplus (linear demand)",level:"beginner",topic:"welfare-measures",tex:"CS = \\tfrac12 (P_{max} - P)\\,Q",symbols:[["P_{max}","demand intercept (choke price)"]],brief:"Buyers' total benefit above what they pay.",meaning:"Changes in CS measure how much consumers gain or lose from price changes.",example:"Choke price 100, price 60, quantity 40: CS = 800.",scenario:"**Case:** demand for mobile data is $P = 100 - Q$. When the price of a data pack falls from Rs 60 to Rs 40, quantity rises from 40 to 60 and consumer surplus rises from 800 to 1,800. The gain of 1,000 is what cheaper data is worth to users, the kind of number a regulator needs.",inputs:[e("pm","Choke price",100),e("p","Price",60),e("q","Quantity",40)],calc:({pm:a,p:t,q:i})=>[{label:"Consumer surplus",value:.5*(a-t)*i}]}),n({id:"dwl-tax",area:"Welfare and taxes",name:"Deadweight loss of a tax (Harberger triangle)",level:"intermediate",topic:"welfare-measures",tex:"DWL = \\tfrac12\\, t\\, \\Delta Q",symbols:[["t","tax per unit"],["\\Delta Q","fall in quantity"]],brief:"The value of trades lost because of a tax.",meaning:"It rises with the square of the tax and with elasticities: tax inelastic bases.",example:"Tax 20, quantity falls by 10: DWL = 100.",scenario:"**Case:** with demand $P = 100 - Q$ and supply $P = 20 + Q$, a tax of 10 cuts quantity from 40 to 35, raises 350 and costs 25 in deadweight loss (7 percent of revenue). A tax of 40 raises 800 but costs 400 (50 percent of revenue). Broad, low rates such as VAT raise money far more cheaply.",inputs:[e("t","Tax per unit",20),e("dq","Fall in quantity",10)],calc:({t:a,dq:t})=>[{label:"Deadweight loss",value:.5*a*t}]}),n({id:"tax-incidence",area:"Welfare and taxes",name:"Tax incidence share",level:"intermediate",tex:"\\text{Buyers' share} = \\frac{\\varepsilon_S}{\\varepsilon_S + |\\varepsilon_D|}",symbols:[["\\varepsilon_S","supply elasticity"],["\\varepsilon_D","demand elasticity"]],brief:"The fraction of a tax borne by buyers.",meaning:"The less elastic side bears more of the tax.",example:"Supply elasticity 2, demand elasticity -0.5: buyers bear 80 percent.",scenario:"**Case (illustrative elasticities):** petrol demand elasticity is -0.2 and import supply is nearly flat with elasticity 5. Buyers bear $5/5.2 = 96$ percent, so a Rs 10 per litre tax raises pump prices by about Rs 9.60.",inputs:[e("s","Supply elasticity",2),e("d","Demand elasticity (absolute)",.5)],calc:({s:a,d:t})=>[{label:"Buyers' share",value:a/(a+t)*100,unit:"%"},{label:"Sellers' share",value:t/(a+t)*100,unit:"%"}]}),n({id:"pigou",area:"Welfare and taxes",name:"Pigouvian tax",level:"intermediate",tex:"t^* = MD(Q^*)",symbols:[["MD","marginal external damage at the efficient quantity"]],brief:"The tax that corrects a negative externality equals marginal external damage at the efficient output.",meaning:"Producers then face the full social cost of their choices.",example:"Each tonne of soot causes damage worth 20: tax 20 per tonne.",scenario:"**Case (illustrative):** each 1,000 bricks fired in a traditional kiln causes soot damage to health worth Rs 500. A charge of Rs 500 per 1,000 bricks makes the kiln pay that cost, so cleaner kiln designs become profitable whenever they cost less than the charge they save.",inputs:[e("md","Marginal damage per unit",20)],calc:({md:a})=>[{label:"Corrective tax per unit",value:a}]}),n({id:"laffer-peak",area:"Welfare and taxes",name:"Revenue maximising tax rate",level:"advanced",tex:"t^* = \\frac{1}{1 + e}",symbols:[["e","elasticity of the tax base to the net of tax rate"]],brief:"The top of the Laffer curve for a simple base.",meaning:"The more responsive the base, the lower the revenue maximising rate. Optimal rates are lower still once taxpayers' welfare counts.",example:"e = 0.25: $t^* = 80$ percent; e = 1: 50 percent.",scenario:"Estimating how far Nepal's top income tax rate is from the revenue peak requires an estimate of e.",inputs:[e("e","Elasticity",.25)],calc:({e:a})=>[{label:"Revenue maximising rate",value:100/(1+a),unit:"%"}]}),n({id:"gdp-expenditure",area:"National accounts and the macroeconomy",name:"GDP by expenditure",level:"beginner",topic:"national-accounts",tex:"Y = C + I + G + (X - M)",symbols:[["C","consumption"],["I","investment"],["G","government purchases"],["X - M","net exports"]],brief:"GDP equals spending on final goods and services produced at home.",meaning:"Imports are subtracted because they are included in C, I and G but not produced at home.",example:"C = 800, I = 300, G = 150, X = 100, M = 350: Y = 1,000.",scenario:"In Nepal, consumption and imports are both very large relative to GDP because remittances fund spending.",inputs:[e("C","C",800),e("I","I",300),e("G","G",150),e("X","X",100),e("M","M",350)],calc:({C:a,I:t,G:i,X:r,M:o})=>[{label:"GDP",value:a+t+i+r-o},{label:"Trade balance",value:r-o}]}),n({id:"gni",area:"National accounts and the macroeconomy",name:"From GDP to national disposable income",level:"intermediate",tex:"GNDI = GDP + NFI + \\text{net current transfers}",symbols:[["NFI","net factor income from abroad"]],brief:"Income available to a country's residents, including remittances.",meaning:"For remittance economies, GNDI is much larger than GDP.",example:"GDP 1,000, net factor income 10, remittances 250: GNDI = 1,260.",scenario:"**Case (approximate, 2023/24):** with GDP of about Rs 5,700 billion and remittances of about a quarter of GDP, national disposable income is roughly 25 percent larger than GDP. Households can then consume close to all of GDP and still save, which is why consumption and imports are so high relative to Nepal's GDP.",inputs:[e("y","GDP",1e3),e("n","Net factor income",10),e("r","Net transfers (remittances)",250)],calc:({y:a,n:t,r:i})=>[{label:"National disposable income",value:a+t+i}]}),n({id:"saving-investment",area:"National accounts and the macroeconomy",name:"Saving, investment and the current account",level:"intermediate",tex:"CA = S - I",symbols:[["CA","current account balance"],["S","national saving"],["I","investment"]],brief:"A country that invests more than it saves must borrow from abroad.",meaning:"A current account deficit is the gap between investment and national saving.",example:"Saving 250, investment 300: current account -50.",scenario:"Large remittances raise Nepal's national saving and can keep the current account near balance despite a big trade deficit.",inputs:[e("S","National saving",250),e("I","Investment",300)],calc:({S:a,I:t})=>[{label:"Current account",value:a-t}]}),n({id:"multiplier",area:"National accounts and the macroeconomy",name:"Spending multiplier (open economy)",level:"intermediate",topic:"is-lm-ad-as",tex:"k = \\frac{1}{1 - c(1 - t) + m}",symbols:[["c","marginal propensity to consume"],["t","tax rate"],["m","marginal propensity to import"]],brief:"How much output rises per unit of extra spending, allowing for taxes and imports.",meaning:"Imports leak spending abroad and shrink the multiplier.",example:"c = 0.8, t = 0.2, m = 0.3: k = 1/(1 - 0.64 + 0.3) = 1.52.",scenario:"**Case:** with MPC 0.8, tax rate 0.15 and import propensity 0.45, the multiplier is $1/(1 - 0.68 + 0.45) = 1.30$. A Rs 100 billion road programme raises GDP by about Rs 130 billion, against Rs 500 billion in a closed economy without taxes. Imports leak most of the stimulus abroad.",inputs:[e("c","MPC",.8),e("t","Tax rate",.2),e("m","Import propensity",.3),e("dg","Change in spending",100)],calc:({c:a,t,m:i,dg:r})=>{const o=1/(1-a*(1-t)+i);return[{label:"Multiplier",value:o},{label:"Change in output",value:o*r}]}}),n({id:"okun",area:"National accounts and the macroeconomy",name:"Okun's law",level:"intermediate",tex:"\\frac{Y - Y^*}{Y^*} = -\\beta\\,(u - u^*)",symbols:[["Y^*","potential output"],["u^*","natural unemployment rate"]],brief:"Output falls about two percent below potential for each point of unemployment above its natural rate (US style estimate).",meaning:"A rule of thumb linking the output gap to unemployment; the coefficient differs by country.",example:"$\\beta = 2$, unemployment 7 percent versus natural 5: output gap -4 percent.",scenario:"In Nepal, with large informality and migration, the link between output and measured unemployment is weak.",inputs:[e("b","Okun coefficient",2),e("u","Unemployment (%)",7),e("un","Natural rate (%)",5)],calc:({b:a,u:t,un:i})=>[{label:"Output gap",value:-a*(t-i),unit:"%"}]}),n({id:"solow-ss",area:"Growth models",name:"Solow steady state",level:"intermediate",topic:"solow",tex:"k^* = \\left(\\frac{s}{n + \\delta}\\right)^{\\frac{1}{1-\\alpha}}",symbols:[["s","saving rate"],["n","population growth"],["\\delta","depreciation"],["\\alpha","capital share"]],brief:"Capital per worker in the long run.",meaning:"Higher saving or lower population growth raises the level of income, not the long run growth rate.",example:"s = 0.25, n + d = 0.07, alpha = 1/3: k* = 6.75, y* = 1.89.",scenario:"**Case:** compare an investment rate of 25 percent with 35 percent, with n + d = 0.07 and capital share one third. Long run income per worker is $(35/25)^{0.5} = 1.18$ times higher: 18 percent, not 40 percent. Investment raises income levels, but productivity decides how much.",inputs:[e("s","Saving rate",.25),e("nd","n + delta",.07),e("a","alpha",.3333)],calc:({s:a,nd:t,a:i})=>{const r=(a/t)**(1/(1-i));return[{label:"k*",value:r},{label:"y*",value:r**i},{label:"c*",value:(1-a)*r**i}]}}),n({id:"growth-accounting",area:"Growth models",name:"Growth accounting",level:"intermediate",tex:"g_Y = g_A + \\alpha\\, g_K + (1 - \\alpha)\\, g_L",symbols:[["g","growth rates"],["A","total factor productivity"]],brief:"Splits output growth into contributions from capital, labour and productivity.",meaning:"TFP growth is the residual: growth not explained by inputs.",example:"Output 5 percent, capital 6, labour 2, alpha 0.35: TFP = 5 - 2.1 - 1.3 = 1.6 percent.",scenario:"How much of Nepal's growth came from more workers and capital, and how much from productivity?",inputs:[e("y","Output growth (%)",5),e("k","Capital growth (%)",6),e("l","Labour growth (%)",2),e("a","alpha",.35)],calc:({y:a,k:t,l:i,a:r})=>[{label:"TFP growth",value:a-r*t-(1-r)*i,unit:"%"}]}),n({id:"golden-rule",area:"Growth models",name:"Golden rule",level:"advanced",topic:"solow",tex:"f'(k_{gold}) = n + \\delta,\\quad s_{gold} = \\alpha",symbols:[["f'(k)","marginal product of capital"]],brief:"The steady state with the highest consumption per worker.",meaning:"With Cobb-Douglas, save the capital share of income.",example:"alpha = 0.33, n + d = 0.07: $k_{gold} = (0.33/0.07)^{1/0.67} = 10.1$.",scenario:"**Case:** with a capital share of 0.35, a country saving 45 percent of income may be above the golden rule: it could consume more forever by saving less. A country saving 15 percent is below it, so more productive investment would raise long run consumption.",inputs:[e("a","alpha",.33),e("nd","n + delta",.07)],calc:({a,nd:t})=>[{label:"k gold",value:(a/t)**(1/(1-a))},{label:"Golden rule saving rate",value:a*100,unit:"%"}]}),n({id:"convergence",area:"Growth models",name:"Speed of convergence",level:"advanced",tex:"\\lambda = (1 - \\alpha)(n + g + \\delta)",symbols:[["\\lambda","share of the gap to the steady state closed each year"]],brief:"How fast an economy approaches its steady state in the Solow model.",meaning:"Half life of the gap is $\\ln 2/\\lambda$.",example:"alpha 0.33, n + g + d = 0.06: $\\lambda = 0.04$, half life about 17 years.",scenario:"**Case:** with a convergence speed of 4 percent, a country at one tenth of its steady state income (log gap 2.3) needs $\\ln(2.3/0.69)/0.04 = 30$ years to reach half of it. Catching up is a project of decades, even with good policy.",inputs:[e("a","alpha",.33),e("s","n + g + delta",.06)],calc:({a,s:t})=>{const i=(1-a)*t;return[{label:"Speed",value:i*100,unit:"% a year"},{label:"Half life",value:Math.log(2)/i,unit:"years"}]}}),n({id:"quantity-theory",area:"Money, inflation and interest",name:"Quantity theory of money",level:"beginner",tex:"MV = PY \\;\\Rightarrow\\; \\pi \\approx g_M + g_V - g_Y",symbols:[["M","money"],["V","velocity"],["P","price level"],["Y","real output"]],brief:"With stable velocity, inflation is money growth minus real growth.",meaning:"A long run relationship; in the short run velocity and output move.",example:"Money grows 12 percent, output 4, velocity stable: inflation about 8 percent.",scenario:"Under Nepal's peg, money supply adjusts to keep the peg, so inflation follows India's more than domestic money growth.",inputs:[e("m","Money growth (%)",12),e("v","Velocity growth (%)",0),e("y","Real growth (%)",4)],calc:({m:a,v:t,y:i})=>[{label:"Inflation",value:a+t-i,unit:"%"}]}),n({id:"fisher",area:"Money, inflation and interest",name:"Fisher equation",level:"beginner",tex:"1 + i = (1 + r)(1 + \\pi^e) \\;\\Rightarrow\\; r \\approx i - \\pi^e",symbols:[["i","nominal rate"],["r","real rate"],["\\pi^e","expected inflation"]],brief:"The nominal interest rate equals the real rate plus expected inflation.",meaning:"Savers care about the real rate.",example:"Deposit rate 8 percent, inflation 6: real rate 1.89 percent exactly.",scenario:"**Case:** a fixed deposit pays 7 percent and inflation is 5.5 percent: the real return is 1.42 percent. After a 6 percent tax on interest the nominal return is 6.58 percent and the real return only 1.02 percent.",inputs:[e("i","Nominal rate (%)",8),e("p","Inflation (%)",6)],calc:({i:a,p:t})=>[{label:"Exact real rate",value:((1+a/100)/(1+t/100)-1)*100,unit:"%"},{label:"Approximation",value:a-t,unit:"%"}]}),n({id:"taylor",area:"Money, inflation and interest",name:"Taylor rule",level:"intermediate",tex:"i = r^* + \\pi + 0.5(\\pi - \\pi^*) + 0.5(y - y^*)",symbols:[["r^*","neutral real rate"],["\\pi^*","inflation target"],["y - y^*","output gap"]],brief:"A simple guide for setting the policy rate.",meaning:"Raise the nominal rate more than one for one with inflation (Taylor principle).",example:"r* = 2, inflation 5, target 4, gap -1: i = 7.",scenario:"Comparing Nepal Rastra Bank's policy rate with a Taylor rule shows the stance, though the peg constrains policy.",inputs:[e("r","Neutral real rate",2),e("p","Inflation",5),e("t","Target",4),e("g","Output gap",-1)],calc:({r:a,p:t,t:i,g:r})=>[{label:"Policy rate",value:a+t+.5*(t-i)+.5*r,unit:"%"}]}),n({id:"money-multiplier",area:"Money, inflation and interest",name:"Money multiplier",level:"intermediate",tex:"m = \\frac{1 + c}{c + r}",symbols:[["c","currency to deposit ratio"],["r","reserve ratio"]],brief:"How much broad money is created per unit of base money in the simple model.",meaning:"Higher reserve requirements or cash holding lower the multiplier.",example:"c = 0.2, r = 0.05: m = 4.8.",scenario:"**Case:** with a currency ratio of 0.15, cutting the cash reserve ratio from 4 to 3 percent raises the multiplier from 6.05 to 6.39, about 5.6 percent more broad money for the same base money in this simple model.",inputs:[e("c","Currency ratio",.2),e("r","Reserve ratio",.05)],calc:({c:a,r:t})=>[{label:"Multiplier",value:(1+a)/(a+t)}]}),n({id:"seigniorage",area:"Money, inflation and interest",name:"Inflation tax (seigniorage)",level:"advanced",tex:"S = \\pi \\cdot \\frac{M}{P}",symbols:[["M/P","real money balances"]],brief:"The real revenue a government gains when inflation erodes money holdings.",meaning:"High inflation raises the rate but lowers money holdings, so revenue has a peak.",example:"Inflation 10 percent on real balances of 500: 50.",scenario:"**Case:** 10 percent inflation on real money balances worth 20 percent of GDP raises about 2 percent of GDP. But people hold less money when inflation is high, so pushing inflation higher eventually raises less, as hyperinflations show.",inputs:[e("p","Inflation (%)",10),e("m","Real money balances",500)],calc:({p:a,m:t})=>[{label:"Seigniorage",value:a/100*t}]}),n({id:"real-exchange",area:"Open economy",name:"Real exchange rate",level:"intermediate",tex:"q = \\frac{e\\,P^*}{P}",symbols:[["e","home currency per foreign currency"],["P^*","foreign prices"],["P","home prices"]],brief:"The relative price of foreign goods in terms of home goods.",meaning:"A rise in q is a real depreciation: home goods become cheaper abroad.",example:"e = 1.6, foreign index 100, home index 110: q = 1.45.",scenario:"With a fixed rate of 1.6 per Indian rupee, faster inflation in Nepal than India means real appreciation, hurting competitiveness.",inputs:[e("e","Nominal rate",1.6),e("ps","Foreign price index",100),e("p","Home price index",110)],calc:({e:a,ps:t,p:i})=>[{label:"Real exchange rate",value:a*t/i}]}),n({id:"ppp",area:"Open economy",name:"Relative purchasing power parity",level:"intermediate",tex:"\\%\\Delta e \\approx \\pi - \\pi^*",symbols:[["\\pi, \\pi^*","home and foreign inflation"]],brief:"Over the long run the currency of the high inflation country tends to depreciate by the inflation gap.",meaning:"Holds poorly in the short run, better over decades.",example:"Home inflation 7 percent, foreign 3: expect about 4 percent depreciation.",scenario:"Testing whether the Nepali rupee's value against the dollar tracks the inflation gap with the US.",inputs:[e("p","Home inflation",7),e("ps","Foreign inflation",3)],calc:({p:a,ps:t})=>[{label:"Expected depreciation",value:a-t,unit:"%"}]}),n({id:"uip",area:"Open economy",name:"Uncovered interest parity",level:"advanced",tex:"i = i^* + \\frac{E[e_{t+1}] - e_t}{e_t}",symbols:[["i^*","foreign interest rate"]],brief:"Expected returns should be equal across currencies.",meaning:"A higher home interest rate must be offset by expected depreciation; often rejected in data.",example:"Home 9 percent, foreign 4: expected depreciation 5 percent.",scenario:"With a credible peg, expected depreciation is near zero, so Nepal's rates must stay close to India's.",inputs:[e("i","Home rate",9),e("is","Foreign rate",4)],calc:({i:a,is:t})=>[{label:"Implied expected depreciation",value:a-t,unit:"%"}]}),n({id:"marshall-lerner",area:"Open economy",name:"Marshall-Lerner condition",level:"advanced",tex:"|\\varepsilon_X| + |\\varepsilon_M| > 1",symbols:[["\\varepsilon_X, \\varepsilon_M","export and import price elasticities"]],brief:"A depreciation improves the trade balance if the elasticities sum to more than one.",meaning:"In the short run elasticities are small, so the balance can worsen first (J curve).",example:"Export elasticity 0.6, import elasticity 0.3: sum 0.9, the condition fails.",scenario:"Nepal's imports are dominated by essentials with low elasticities, so devaluation may not shrink the deficit much.",inputs:[e("x","Export elasticity",.6),e("m","Import elasticity",.3)],calc:({x:a,m:t})=>[{label:"Sum",value:Math.abs(a)+Math.abs(t)}]}),n({id:"reserve-cover",area:"Open economy",name:"Import cover of reserves",level:"beginner",tex:"\\text{Months} = \\frac{\\text{Reserves}}{\\text{Monthly imports}}",symbols:[],brief:"How many months of imports foreign exchange reserves could pay for.",meaning:"A common rule of thumb is at least three months; peg regimes need more.",example:"Reserves 15 billion dollars, annual imports 15 billion: 12 months.",scenario:"**Case (illustrative):** reserves of 15 billion dollars and annual imports of 13 billion give 13.8 months of cover. The usual minimum is three months; a pegged currency like the Nepali rupee needs much more, and NRB's monetary policy has aimed for at least seven months.",inputs:[e("r","Reserves",15),e("m","Annual imports",15)],calc:({r:a,m:t})=>[{label:"Months of import cover",value:a/(t/12)}]}),n({id:"pv",area:"Finance and discounting",name:"Present value",level:"beginner",tex:"PV = \\frac{FV}{(1 + r)^T}",symbols:[["FV","future value"],["r","discount rate"],["T","years"]],brief:"What a future amount is worth today.",meaning:"Money now can earn interest, so future money is worth less.",example:"10,000 in 5 years at 8 percent: 6,805.83.",scenario:"**Case:** a gratuity of Rs 1,000,000 paid in 20 years, discounted at 8 percent, is worth $1{,}000{,}000/1.08^{20} = 214{,}548$ today. Comparing job offers requires converting such future payments to present values.",inputs:[e("fv","Future value",1e4),e("r","Rate (%)",8),e("T","Years",5)],calc:({fv:a,r:t,T:i})=>[{label:"Present value",value:a/(1+t/100)**i}]}),n({id:"fv",area:"Finance and discounting",name:"Compound interest",level:"beginner",tex:"FV = PV\\,(1 + r)^T",symbols:[],brief:"How savings grow with compound interest.",meaning:"Interest earns interest; small rate differences compound into large gaps.",example:"100,000 at 7 percent for 10 years: 196,715.",scenario:"**Case:** saving Rs 200,000 now at 7 percent for three years gives Rs 245,009 for application fees, tests and travel when you apply.",inputs:[e("pv","Today",1e5),e("r","Rate (%)",7),e("T","Years",10)],calc:({pv:a,r:t,T:i})=>[{label:"Future value",value:a*(1+t/100)**i}]}),n({id:"annuity",area:"Finance and discounting",name:"Present value of an annuity",level:"intermediate",tex:"PV = C\\,\\frac{1 - (1 + r)^{-T}}{r}",symbols:[["C","payment each period"]],brief:"Value today of equal payments over T periods.",meaning:"Used for loans, pensions and scholarships paid yearly.",example:"A stipend of 30,000 a year for 5 years at 5 percent: 129,884.",scenario:"**Case:** a stipend of 35,000 dollars a year for five years, discounted at 5 percent, is worth 151,532 dollars today. Use this to compare funding offers with different lengths.",inputs:[e("C","Payment",3e4),e("r","Rate (%)",5),e("T","Periods",5)],calc:({C:a,r:t,T:i})=>[{label:"Present value",value:a*(1-(1+t/100)**-i)/(t/100)}]}),n({id:"loan-payment",area:"Finance and discounting",name:"Loan instalment (EMI)",level:"beginner",tex:"A = P\\,\\frac{r(1 + r)^n}{(1 + r)^n - 1}",symbols:[["P","principal"],["r","rate per period"],["n","number of instalments"]],brief:"Equal payment that repays a loan with interest.",meaning:"The annuity formula solved for the payment.",example:"Loan 1,000,000 at 12 percent a year, monthly for 5 years: 22,244 a month.",scenario:"**Case:** a home loan of Rs 5,000,000 at 11 percent for 20 years has a monthly instalment of about Rs 51,609. Over the loan you repay about Rs 12.4 million, more than twice the amount borrowed.",inputs:[e("P","Principal",1e6),e("r","Annual rate (%)",12),e("n","Months",60)],calc:({P:a,r:t,n:i})=>{const r=t/1200;return[{label:"Monthly instalment",value:a*r*(1+r)**i/((1+r)**i-1)}]}}),n({id:"perpetuity",area:"Finance and discounting",name:"Growing perpetuity (Gordon)",level:"intermediate",tex:"PV = \\frac{C_1}{r - g}",symbols:[["g","growth rate of payments"]],brief:"Value of a payment stream growing forever at rate g.",meaning:"Basis of dividend discount valuation of shares.",example:"Dividend 50 next year, required return 12 percent, growth 4: 625.",scenario:"**Case:** a bank share paying a Rs 20 dividend next year, growing 5 percent, with a required return of 12 percent is worth Rs 285.7. If interest rates rise and the required return becomes 14 percent, it is worth Rs 222.2, a 22 percent fall. This is why share prices fall when rates rise.",inputs:[e("c","Next payment",50),e("r","Required return (%)",12),e("g","Growth (%)",4)],calc:({c:a,r:t,g:i})=>[{label:"Value",value:a/((t-i)/100)}]}),n({id:"npv",area:"Finance and discounting",name:"Net present value",level:"intermediate",tex:"NPV = -I_0 + \\sum_{t=1}^{T} \\frac{CF_t}{(1 + r)^t}",symbols:[["I_0","initial cost"],["CF_t","cash flow in year t"]],brief:"Present value of benefits minus costs.",meaning:"Invest if NPV is positive at the right discount rate.",example:"Cost 1,000; 400 a year for 3 years at 10 percent: NPV = -5.26.",scenario:"**Case (illustrative):** a micro hydro plant costs Rs 10 million and earns Rs 1.5 million a year for 15 years. At 10 percent the NPV is about Rs 1.41 million, at 12 percent about Rs 0.22 million, and at 13 percent it turns negative. The discount rate decides the project.",inputs:[e("i","Initial cost",1e3),e("c","Cash flow per year",400),e("r","Rate (%)",10),e("T","Years",3)],calc:({i:a,c:t,r:i,T:r})=>{let o=0;for(let s=1;s<=r;s++)o+=t/(1+i/100)**s;return[{label:"NPV",value:o-a}]}}),n({id:"capm",area:"Finance and discounting",name:"Capital asset pricing model",level:"advanced",tex:"E[R_i] = R_f + \\beta_i\\,(E[R_m] - R_f)",symbols:[["R_f","risk free rate"],["\\beta_i","sensitivity to the market"],["R_m","market return"]],brief:"Expected return rises with systematic risk.",meaning:"Only market risk (beta) is rewarded; diversifiable risk is not.",example:"Risk free 5, market 12, beta 1.2: 13.4 percent.",scenario:"**Case:** with a risk free rate of 6 percent, a market return of 13 percent and beta 1.3, a hydropower company's shareholders require 15.1 percent. A new project returning 12 percent would destroy value for them.",inputs:[e("rf","Risk free (%)",5),e("rm","Market return (%)",12),e("b","Beta",1.2)],calc:({rf:a,rm:t,b:i})=>[{label:"Expected return",value:a+i*(t-a),unit:"%"}]}),n({id:"sharpe",area:"Finance and discounting",name:"Sharpe ratio",level:"intermediate",tex:"SR = \\frac{E[R] - R_f}{\\sigma}",symbols:[["\\sigma","standard deviation of returns"]],brief:"Excess return per unit of risk.",meaning:"Compares portfolios with different risk.",example:"Return 14, risk free 6, volatility 20: 0.4.",scenario:"**Case:** fund A returns 18 percent with 25 percent volatility, fund B 14 percent with 12 percent volatility, and the risk free rate is 6 percent. Sharpe ratios are 0.48 and 0.67: B rewards risk better despite a lower return.",inputs:[e("r","Return (%)",14),e("rf","Risk free (%)",6),e("s","Volatility (%)",20)],calc:({r:a,rf:t,s:i})=>[{label:"Sharpe ratio",value:(a-t)/i}]}),n({id:"expected-value",area:"Probability",name:"Expected value and variance",level:"beginner",topic:"random-variables",tex:"E[X] = \\sum x_i p_i,\\quad Var(X) = E[X^2] - (E[X])^2",symbols:[],brief:"The average outcome and its spread.",meaning:"Variance measures risk around the average.",example:"Outcomes 0 and 100 with probabilities 0.5: mean 50, variance 2,500.",scenario:"**Case:** a farmer harvests 3,000 kg in a good monsoon (probability 0.7) and 1,800 kg in a bad one. Expected harvest is 2,640 kg with a standard deviation of about 550 kg. Insurance or storage reduces this risk.",inputs:[e("a","Outcome 1",0),e("b","Outcome 2",100),e("p","Probability of outcome 2",.5)],calc:({a,b:t,p:i})=>{const r=(1-i)*a+i*t;return[{label:"Mean",value:r},{label:"Variance",value:(1-i)*a*a+i*t*t-r*r}]}}),n({id:"bayes",area:"Probability",name:"Bayes' rule",level:"intermediate",topic:"probability-basics",tex:"P(A\\mid B) = \\frac{P(B\\mid A)\\,P(A)}{P(B)}",symbols:[],brief:"Updates a probability with new evidence.",meaning:"Base rates matter: a positive signal about a rare event still leaves it fairly unlikely.",example:"Prevalence 2 percent, sensitivity 90, false positives 5: P = 0.269.",scenario:"**Case:** 5 percent of microfinance borrowers default; a screening model flags 80 percent of defaulters and 10 percent of good borrowers. A flagged borrower defaults with probability $0.04/(0.04 + 0.095) = 0.30$: most flagged borrowers repay.",inputs:[e("p","Prior P(A)",.02),e("s","P(B given A)",.9),e("f","P(B given not A)",.05)],calc:({p:a,s:t,f:i})=>[{label:"Posterior P(A given B)",value:t*a/(t*a+i*(1-a))}]}),n({id:"binomial",area:"Probability",name:"Binomial probability",level:"intermediate",tex:"P(X = k) = \\binom{n}{k} p^k (1 - p)^{n - k}",symbols:[["n","trials"],["k","successes"]],brief:"Probability of k successes in n independent trials.",meaning:"Mean np, variance np(1 - p).",example:"n = 5, k = 2, p = 0.3: 0.3087.",scenario:"**Case (illustrative):** if 55 percent of households receive remittances, the chance that all 5 sampled households do is $0.55^5 = 0.05$, and that none do is $0.45^5 = 0.018$. Small samples can easily mislead.",inputs:[e("n","n",5),e("k","k",2),e("p","p",.3)],calc:({n:a,k:t,p:i})=>{let r=1;for(let o=0;o<t;o++)r=r*(a-o)/(o+1);return[{label:"Probability",value:r*i**t*(1-i)**(a-t)}]}}),n({id:"covariance",area:"Probability",name:"Correlation from covariance",level:"beginner",tex:"\\rho = \\frac{Cov(X, Y)}{\\sigma_X \\sigma_Y}",symbols:[],brief:"A unit free measure of linear association between minus one and one.",meaning:"Correlation is not causation.",example:"Covariance 12, standard deviations 4 and 5: 0.6.",scenario:"**Case:** across 77 districts, rainfall and rice yields have covariance 12 with standard deviations 4 and 5: correlation 0.6. Rainfall then accounts for 36 percent of the variation in yields ($0.6^2$), but other causes may move with rainfall.",inputs:[e("c","Covariance",12),e("a","SD of X",4),e("b","SD of Y",5)],calc:({c:a,a:t,b:i})=>[{label:"Correlation",value:a/(t*i)}]}),n({id:"standard-error",area:"Statistics and inference",name:"Standard error of the mean",level:"beginner",topic:"lln-clt",tex:"SE(\\bar X) = \\frac{s}{\\sqrt n}",symbols:[["s","sample standard deviation"],["n","sample size"]],brief:"Precision of a sample mean.",meaning:"Four times the sample halves the standard error.",example:"s = 20, n = 100: SE = 2.",scenario:"**Case:** monthly spending has a standard deviation of Rs 15,000. A sample of 400 households gives a standard error of Rs 750. Comparing two districts with 100 households each, differences smaller than about Rs 4,200 cannot be told apart from noise.",inputs:[e("s","Standard deviation",20),e("n","Sample size",100)],calc:({s:a,n:t})=>[{label:"Standard error",value:a/Math.sqrt(t)}]}),n({id:"ci",area:"Statistics and inference",name:"95% confidence interval",level:"beginner",topic:"hypothesis-testing",tex:"\\bar X \\pm 1.96\\,\\frac{s}{\\sqrt n}",symbols:[],brief:"A range that would contain the true mean in 95 percent of repeated samples.",meaning:"It is a statement about the procedure, not a 95 percent probability for this one interval.",example:"Mean 150, s = 30, n = 100: 144.12 to 155.88.",scenario:"**Case:** a survey of 100 households finds mean monthly spending of Rs 35,000 with standard deviation Rs 12,000. The 95 percent interval is Rs 32,648 to Rs 37,352. Report the interval, not just the mean.",inputs:[e("m","Mean",150),e("s","SD",30),e("n","n",100)],calc:({m:a,s:t,n:i})=>[{label:"Lower",value:a-1.96*t/Math.sqrt(i)},{label:"Upper",value:a+1.96*t/Math.sqrt(i)}]}),n({id:"t-stat",area:"Statistics and inference",name:"t statistic",level:"beginner",topic:"ols-inference",tex:"t = \\frac{\\hat\\beta - \\beta_0}{SE(\\hat\\beta)}",symbols:[["\\beta_0","hypothesised value, usually 0"]],brief:"How many standard errors an estimate is from the hypothesised value.",meaning:"|t| > 1.96 rejects at 5 percent in large samples.",example:"Estimate 0.8, SE 0.3: t = 2.67, significant.",scenario:"**Case:** remittances are associated with 0.12 more years of schooling, standard error 0.05: t = 2.4, significant at 5 percent. If clustering by village raises the standard error to 0.08, t = 1.5 and it is no longer significant. Get the standard errors right.",inputs:[e("b","Estimate",.8),e("b0","Hypothesised value",0),e("se","Standard error",.3)],calc:({b:a,b0:t,se:i})=>[{label:"t",value:(a-t)/i}]}),n({id:"sample-size",area:"Statistics and inference",name:"Sample size for a target margin",level:"intermediate",tex:"n = \\left(\\frac{1.96\\,\\sigma}{E}\\right)^2",symbols:[["E","desired margin of error"]],brief:"How many observations you need for a given precision.",meaning:"Halving the margin needs four times the sample.",example:"sigma 30, margin 3: $(58.8/3)^2 = 384.2$, so round up to n = 385.",scenario:"**Case:** spending has a standard deviation of Rs 12,000 and you want a margin of Rs 1,000: you need 554 households. At Rs 800 an interview that costs Rs 443,200. Halving the margin to Rs 500 needs 2,213 households, four times the cost.",inputs:[e("s","Standard deviation",30),e("e","Margin of error",3)],calc:({s:a,e:t})=>[{label:"Required n",value:Math.ceil((1.96*a/t)**2)}]}),n({id:"mde",area:"Statistics and inference",name:"Minimum detectable effect (two group RCT)",level:"advanced",tex:"MDE = (z_{1-\\alpha/2} + z_{1-\\kappa})\\,\\sigma\\sqrt{\\frac{1}{P(1-P)N}}",symbols:[["P","share treated"],["N","total sample"],["\\kappa","power"]],brief:"The smallest true effect an experiment can reliably detect.",meaning:"With 5 percent size and 80 percent power the factor is about 2.8.",example:"sigma 1, N = 400, half treated: MDE = 2.8 x 0.1 = 0.28 standard deviations.",scenario:"**Case:** a pilot with 300 households, half treated, can detect effects of about 0.32 standard deviations. If you expect 0.2, you need $(2.8/0.2)^2/0.25 = 784$ households. Do this calculation before fieldwork, not after.",inputs:[e("s","Outcome SD",1),e("N","Total sample",400),e("P","Share treated",.5)],calc:({s:a,N:t,P:i})=>[{label:"MDE",value:2.8*a*Math.sqrt(1/(i*(1-i)*t))}]}),n({id:"ols-slope",area:"Regression and causal inference",name:"OLS slope",level:"beginner",topic:"ols-simple",tex:"\\hat\\beta = \\frac{Cov(x, y)}{Var(x)}",symbols:[],brief:"The slope of the best fitting line.",meaning:"Equals correlation times the ratio of standard deviations.",example:"Cov 24, Var(x) 8: slope 3.",scenario:"**Case:** if the covariance of schooling and log wages is 0.6 and the variance of schooling is 8, the slope is 0.075: each extra year goes with about 7.8 percent higher wages. Whether that is causal is a separate question.",inputs:[e("c","Cov(x, y)",24),e("v","Var(x)",8)],calc:({c:a,v:t})=>[{label:"Slope",value:a/t}]}),n({id:"ovb",area:"Regression and causal inference",name:"Omitted variable bias",level:"intermediate",topic:"endogeneity-iv",tex:"E[\\tilde\\beta_1] = \\beta_1 + \\beta_2\\,\\delta",symbols:[["\\beta_2","effect of the omitted variable on y"],["\\delta","slope of the omitted variable on x"]],brief:"Bias from leaving out a variable that affects y and is correlated with x.",meaning:"Sign of bias = sign of $\\beta_2$ times sign of $\\delta$.",example:"True effect 0.08, ability effect 0.05, ability on schooling 0.4: estimate 0.10.",scenario:"Returns to schooling in Nepal are overstated if able children both study longer and earn more.",inputs:[e("b1","True effect",.08),e("b2","Effect of omitted variable",.05),e("d","Omitted on x",.4)],calc:({b1:a,b2:t,d:i})=>[{label:"Biased estimate",value:a+t*i},{label:"Bias",value:t*i}]}),n({id:"wald-iv",area:"Regression and causal inference",name:"IV (Wald) estimator",level:"intermediate",topic:"endogeneity-iv",tex:"\\hat\\beta_{IV} = \\frac{\\text{reduced form}}{\\text{first stage}} = \\frac{Cov(z, y)}{Cov(z, x)}",symbols:[["z","instrument"]],brief:"The causal effect from an instrument: effect of z on y divided by effect of z on x.",meaning:"Valid if z moves x and affects y only through x.",example:"Reduced form 0.6, first stage 0.2: effect 3.",scenario:"**Case:** children living 1 km closer to a school get 0.5 more years of schooling (first stage) and later earn 4 percent more (reduced form). IV gives $0.04/0.5 = 0.08$, 8 percent per year. It is valid only if distance affects earnings through schooling alone; villages near schools may also be near roads and markets.",inputs:[e("rf","Reduced form",.6),e("fs","First stage",.2)],calc:({rf:a,fs:t})=>[{label:"IV estimate",value:a/t}]}),n({id:"did",area:"Regression and causal inference",name:"Difference-in-differences",level:"beginner",topic:"did",tex:"\\hat\\delta = (\\bar y_{T,post} - \\bar y_{T,pre}) - (\\bar y_{C,post} - \\bar y_{C,pre})",symbols:[["T, C","treated and comparison groups"]],brief:"The change in the treated group minus the change in the comparison group.",meaning:"Valid under parallel trends.",example:"Treated 40 to 52, comparison 38 to 44: 12 - 6 = 6.",scenario:"**Case (illustrative):** after school meals start, attendance in pilot districts rises from 78 to 86 percent and in comparison districts from 80 to 83 percent. DiD = 8 - 3 = 5 percentage points, if trends would have been parallel.",inputs:[e("a","Treated before",40),e("b","Treated after",52),e("c","Comparison before",38),e("d","Comparison after",44)],calc:({a,b:t,c:i,d:r})=>[{label:"DiD estimate",value:t-a-(r-i)}]}),n({id:"r-squared",area:"Regression and causal inference",name:"R-squared and adjusted R-squared",level:"beginner",tex:"R^2 = 1 - \\frac{SSR}{SST},\\quad \\bar R^2 = 1 - (1 - R^2)\\frac{n - 1}{n - k - 1}",symbols:[["k","number of regressors"]],brief:"Share of variation explained, with a penalty for extra regressors.",meaning:"A low R-squared does not make a causal estimate wrong.",example:"SSR 300, SST 1,000, n = 100, k = 3: 0.70 and 0.69.",scenario:"Wage regressions for Nepal explain little variation, yet the schooling coefficient can still be credible.",inputs:[e("ssr","SSR",300),e("sst","SST",1e3),e("n","n",100),e("k","k",3)],calc:({ssr:a,sst:t,n:i,k:r})=>{const o=1-a/t;return[{label:"R-squared",value:o},{label:"Adjusted",value:1-(1-o)*(i-1)/(i-r-1)}]}}),n({id:"log-coef",area:"Regression and causal inference",name:"Interpreting a log-level coefficient",level:"beginner",topic:"functional-form",tex:"\\%\\Delta y = 100\\,(e^{\\beta \\Delta x} - 1)",symbols:[["\\beta","coefficient on x in a log y regression"]],brief:"The exact percentage change in y from a change in x.",meaning:"For small beta, about 100 beta percent per unit.",example:"beta = 0.08: one more year of schooling raises wages by 8.33 percent.",scenario:"**Case:** with a coefficient of 0.08 on years of schooling, a bachelor's graduate (14 years) earns $e^{0.32} - 1 = 37.7$ percent more than a school leaver with 10 years, other things equal.",inputs:[e("b","Coefficient",.08),e("dx","Change in x",1)],calc:({b:a,dx:t})=>[{label:"Exact % change",value:100*(Math.exp(a*t)-1),unit:"%"},{label:"Approximate",value:100*a*t,unit:"%"}]}),n({id:"ar1-mean",area:"Time series",name:"AR(1): long run mean and half life",level:"intermediate",topic:"time-series-arma",tex:"y_t = c + \\rho y_{t-1} + \\varepsilon_t,\\quad \\mu = \\frac{c}{1-\\rho}",symbols:[["\\rho","persistence"]],brief:"A series pulled back toward its mean at speed set by rho.",meaning:"Half life of a shock: $\\ln 0.5 / \\ln \\rho$.",example:"c = 2, rho = 0.6: mean 5, half life 1.36 periods.",scenario:"**Case:** if year on year inflation has persistence 0.9 around a mean of 5 percent and a food shock lifts it to 8 percent, six months later it is still $5 + 3(0.9^6) = 6.6$ percent. Persistent shocks keep the central bank cautious.",inputs:[e("c","Constant",2),e("r","rho",.6)],calc:({c:a,r:t})=>[{label:"Long run mean",value:a/(1-t)},{label:"Half life",value:Math.log(.5)/Math.log(t)}]}),n({id:"moving-average",area:"Time series",name:"Moving average",level:"beginner",tex:"MA_t = \\frac{1}{k}\\sum_{j=0}^{k-1} y_{t-j}",symbols:[["k","window length"]],brief:"Smooths a series by averaging recent values.",meaning:"Removes short run noise to show the trend.",example:"Last three months 4.2, 5.1 and 4.8 percent: 4.7.",scenario:"**Case:** monthly remittance inflows of Rs 110, 95 and 140 billion average Rs 115 billion. A twelve month average removes festival and seasonal spikes, so you can see the trend.",inputs:[e("a","Value 1",4.2),e("b","Value 2",5.1),e("c","Value 3",4.8)],calc:({a,b:t,c:i})=>[{label:"Three period average",value:(a+t+i)/3}]}),n({id:"gini-lorenz",area:"Inequality and poverty",name:"Gini coefficient",level:"intermediate",topic:"poverty-inequality",tex:"G = 1 - 2\\int_0^1 L(p)\\,dp",symbols:[["L(p)","Lorenz curve"]],brief:"Twice the area between equality and the Lorenz curve.",meaning:"0 is complete equality, 1 complete inequality.",example:"With $L(p) = p^2$: $G = 1 - 2/3 = 0.33$.",scenario:"**Case:** a Lorenz curve close to $p^2$ gives a Gini of 0.33. Nepal's consumption Gini in recent living standards surveys has been around 0.30; income Ginis are usually higher than consumption Ginis.",inputs:[e("g","Exponent in L(p) = p^g",2)],calc:({g:a})=>[{label:"Gini",value:1-2/(a+1)}]}),n({id:"fgt",area:"Inequality and poverty",name:"Foster-Greer-Thorbecke poverty measures",level:"intermediate",tex:"P_\\alpha = \\frac{1}{N}\\sum_{i:\\,y_i < z}\\left(\\frac{z - y_i}{z}\\right)^{\\alpha}",symbols:[["z","poverty line"],["\\alpha = 0, 1, 2","headcount, gap, severity"]],brief:"A family of poverty measures: how many are poor, how poor, and inequality among the poor.",meaning:"The poverty gap tells you the cost of ending poverty with perfect targeting.",example:"4 poor people out of 10, each 25 percent below the line: headcount 0.4, gap 0.1, severity 0.025.",scenario:"**Case (illustrative):** in a village of 1,000 people, 200 are poor and their average shortfall is 20 percent of a poverty line of Rs 73,000 a year. Headcount 0.2, poverty gap 0.04. Perfectly targeted transfers to end poverty would cost $200 \\times 0.2 \\times 73{,}000 = $ Rs 2.92 million a year.",inputs:[e("n","Total people",10),e("p","Number poor",4),e("s","Average shortfall share",.25)],calc:({n:a,p:t,s:i})=>[{label:"Headcount",value:t/a},{label:"Poverty gap",value:t/a*i},{label:"Severity (equal shortfalls)",value:t/a*i*i}]}),n({id:"palma",area:"Inequality and poverty",name:"Palma ratio",level:"beginner",tex:"\\text{Palma} = \\frac{\\text{income share of top }10\\%}{\\text{income share of bottom }40\\%}",symbols:[],brief:"Compares the richest tenth with the poorest four tenths.",meaning:"Focuses on the tails where most change in inequality happens.",example:"Top 10 percent hold 30 percent, bottom 40 percent hold 20: 1.5.",scenario:"**Case (illustrative):** if the top 10 percent receive 26 percent of income and the bottom 40 percent receive 20 percent, the Palma ratio is 1.3. One number that a minister can remember.",inputs:[e("t","Top 10% share",30),e("b","Bottom 40% share",20)],calc:({t:a,b:t})=>[{label:"Palma ratio",value:a/t}]}),n({id:"mincer",area:"Labour and human capital",name:"Mincer earnings equation",level:"intermediate",tex:"\\ln w = a + \\rho S + \\beta_1 X + \\beta_2 X^2",symbols:[["S","years of schooling"],["X","experience"]],brief:"Log earnings depend on schooling and a concave experience profile.",meaning:"$\\rho$ is the return to a year of schooling; experience peaks at $-\\beta_1/(2\\beta_2)$.",example:"$\\beta_1 = 0.04$, $\\beta_2 = -0.0007$: earnings peak at 28.6 years of experience.",scenario:"**Case:** with $\\beta_1 = 0.045$ and $\\beta_2 = -0.0008$, earnings peak after about 28 years of experience. Returning migrants' foreign experience can be added as a separate term to test whether it is valued at home.",inputs:[e("b1","beta1",.04),e("b2","beta2",-7e-4)],calc:({b1:a,b2:t})=>[{label:"Experience at peak earnings",value:-a/(2*t),unit:"years"}]}),n({id:"unemployment-rate",area:"Labour and human capital",name:"Labour market rates",level:"beginner",tex:"u = \\frac{U}{E + U},\\quad LFPR = \\frac{E + U}{\\text{working age population}}",symbols:[["E","employed"],["U","unemployed"]],brief:"Unemployment and participation rates.",meaning:"Discouraged workers leave the labour force and lower measured unemployment.",example:"E = 900, U = 100, population 2,000: u = 10 percent, participation 50 percent.",scenario:"**Case:** Nepal's Labour Force Survey 2017/18 reported unemployment of about 11 percent and labour force participation of about 39 percent, much lower for women. Low participation, not only unemployment, is the bigger labour market problem, and migration abroad hides much of it.",inputs:[e("e","Employed",900),e("u","Unemployed",100),e("p","Working age population",2e3)],calc:({e:a,u:t,p:i})=>[{label:"Unemployment rate",value:t/(a+t)*100,unit:"%"},{label:"Participation rate",value:(a+t)/i*100,unit:"%"}]}),n({id:"return-education",area:"Labour and human capital",name:"Internal rate of return to education",level:"advanced",tex:"\\sum_{t} \\frac{\\Delta w_t}{(1 + r)^t} = C_0 \\;\\text{(solve for r)}",symbols:[["\\Delta w_t","extra earnings in year t"],["C_0","cost, including forgone earnings"]],brief:"The discount rate that makes the benefits of education equal its costs.",meaning:"Compare with interest rates to judge whether education pays.",example:"Cost 500,000, extra earnings 60,000 a year for 30 years: about 11.55 percent.",scenario:"**Case (illustrative):** a master's costs Rs 400,000 in fees plus Rs 600,000 of earnings forgone, Rs 1,000,000 in all, and raises earnings by Rs 100,000 a year for 30 years. The internal rate of return is about 9.3 percent: worth it if you can borrow or save at less than that.",inputs:[e("c","Cost",5e5),e("w","Extra earnings per year",6e4),e("T","Years",30)],calc:({c:a,w:t,T:i})=>{let r=1e-4,o=1;for(let s=0;s<80;s++){const l=(r+o)/2;t*(1-(1+l)**-i)/l>a?r=l:o=l}return[{label:"Internal rate of return",value:(r+o)/2*100,unit:"%"}]}})],u=Object.fromEntries(c.map(a=>[a.id,a])),d=a=>Object.fromEntries(a.inputs.map(t=>[t.id,t.value]));export{u as F,c as a,m as b,d as f};
